"""Static exported paths must occupy the same positions as live components."""
from playwright.sync_api import sync_playwright
import os,json
base=os.getenv('TEST_URL','http://127.0.0.1:4173/icons/')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page();page.goto(base,wait_until='networkidle');page.emulate_media(reduced_motion='reduce')
 result=page.evaluate('''async()=>{const {icons}=await(await fetch('./catalog.json')).json();const {staticSVG}=await import('./export.js');const failures=[];let states=0;for(const entry of icons){const{definition:d}=await import('./modules/'+entry.id+'.js');for(const state of entry.states){states++;const host=document.createElement('div');host.style.cssText='position:fixed;left:0;top:0;display:flex;gap:0';const live=document.createElement('lucian-'+d.id);live.setAttribute('size','96');live.setState(state);host.append(live);const exported=document.createElement('div');exported.style.cssText='width:96px;height:96px';exported.innerHTML=staticSVG(d,{state,size:96});host.append(exported);document.body.append(host);const a=live.getBoundingClientRect(),b=exported.getBoundingClientRect();for(const [name]of Object.entries(d.parts)){const x=live.shadowRoot.querySelector('[data-part="'+name+'"]'),y=exported.querySelector('[data-part="'+name+'"]');const r=x.getBoundingClientRect(),s=y.getBoundingClientRect();const delta=Math.max(Math.abs(r.x-a.x-s.x+b.x),Math.abs(r.y-a.y-s.y+b.y),Math.abs(r.width-s.width),Math.abs(r.height-s.height));if(delta>.15)failures.push({id:d.id,state,part:name,delta})}host.remove()}}return{states,failures}}''')
 assert not result['failures'],json.dumps(result['failures'][:12]);print(json.dumps({'static_live_states':result['states'],'geometry_parity':'passed'}));b.close()
